use forge_domain :: Transformer ; use crate :: dto :: anthropic :: Request ; use std :: collections :: HashSet ; use forge_domain :: { Context , ContextMessage , ModelId , Role , TextMessage } ; use pretty_assertions :: assert_eq ; use super :: * ; impl Transformer for SetCache { type Value = Request ; # [doc = " Applies the default Anthropic cache strategy:"] # [doc = " 1. Cache every system message when present, otherwise cache the first"] # [doc = "    conversation message."] # [doc = " 2. Cache only the last message as the rolling message-level marker."] fn transform (& mut self , mut request : Self :: Value) -> Self :: Value { let len = request . get_messages () . len () ; let sys_len = request . system . as_ref () . map_or (0 , | msgs | msgs . len ()) ; if len == 0 && sys_len == 0 { return request ; } let has_system_prompt = request . system . as_ref () . is_some_and (| messages | ! messages . is_empty ()) ; if let Some (system_messages) = request . system . as_mut () { for message in system_messages . iter_mut () { * message = std :: mem :: take (message) . cached (true) ; } } for message in request . get_messages_mut () . iter_mut () { * message = std :: mem :: take (message) . cached (false) ; } if ! has_system_prompt && len > 0 && let Some (first_message) = request . get_messages_mut () . first_mut () { * first_message = std :: mem :: take (first_message) . cached (true) ; } if let Some (message) = request . get_messages_mut () . last_mut () { * message = std :: mem :: take (message) . cached (true) ; } request } }